/**
 * Generated by `npm run arena:rulesets` from `src/lib/arena/rulesets/dbs/*.rules`.
 * Do not edit: edit the `.rules` file and run the script again.
 *
 * The text lives here so the loader can be pure — see the script's header.
 */
export const FILES: Record<string, string> = {
  "actions.rules": "-- The moves a player may make, as declarations rather than as predicates.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §7-3-4 the free timing of the Main\n-- Phase, §7-2-11 the charge, §7-3-5 the end of the Main Phase, §0-1-3-4\n-- conceding.\n--\n-- An action is `WHEN / FOR / COST / DO / REFUSE` (§3b of\n-- `docs/arena-rules-language.md`, \"how an action is declared\" in\n-- `docs/arena-ruleset-spec.md`). `vm/actions.ts` reads all five: `WHEN` and\n-- `prompts:` say which question it is offered at, `FOR` which cards it is\n-- offered for, `REFUSE` the requirement a player is owed for each card it is\n-- *not* offered for, and `COST` and `DO` what taking it costs and does. The\n-- menu and the refusals therefore come from one paragraph, which is the whole\n-- point of the file: nothing below has a hand-written `whyNot` twin.\n--\n-- **Eight so far.** The four that need no payment and no battle came first\n-- (#145), which is what makes them the ones that proved the machinery on a real\n-- turn; the prices followed (#148), and the play family below is the first to\n-- carry one. Activating followed (#147), which is the one whose candidate is a\n-- skill *line*; the battle is Stage 6, and each arrives here as a paragraph\n-- rather than as a branch somewhere else.\n--\n-- `listed: false` is the rule the legacy engine has always had and never\n-- wrote down: a move a client shows as a button of its own is accepted\n-- without ever being enumerated. It says nothing about legality — an unlisted\n-- action is checked exactly as a listed one is — only that it is on neither\n-- the menu nor the list of refusals, because a refusal explains a move a\n-- player can see. `pass` and `concede` are the two.\n\n-- 7-2-11 gives the turn player **one** charge, and the other half of that\n-- sentence is a refusal rather than a silence: the legacy engine offers every\n-- card in hand at the Main Phase question and refuses each with \"you have\n-- already had your charge this turn\". So the move is declared in both phases\n-- and refused in one, over the player attribute §269 added for exactly this:\n-- `charged` (`attributes.rules`), true from the moment the Charge Phase's own\n-- question is answered (`vm/flow.ts`'s `mainPending`) — which is also\n-- `whyNotCharge`'s own reading (\"once the Main Phase has begun, the one\n-- charge of the turn has gone by\"), so the two engines cannot disagree about\n-- what the sentence means. Earlier this REFUSE named `asking(prompt: charge)`\n-- instead, a proxy for the fact rather than the fact itself, which is what\n-- left 13-3's `growUnison` with no word to reuse (issue #269).\nDEFINE ACTION charge                                                      -- §7-2-11\n  WHEN [charge, main]\n  prompts: [charge, main]\n  FOR 1 IN you.hand\n  BIND \"card\"\n  -- 7-2-11 is a *may*, and the half of it that takes no card is an answer of\n  -- its own rather than the absence of one: a candidate, last on the menu, so\n  -- the board keeps the ghost button beside the cards it could have charged\n  -- (`docs/arena-hud-spec.md` §2.3). The `DO` below is written about the\n  -- candidate, so declining runs it over no cards and moves nothing. It is an\n  -- answer to *this* question, so the board-level refusal below takes it off\n  -- the menu entirely at the Main Phase rather than greying it out: there is no\n  -- skip button there to explain.\n  decline: \"Skip charge\"\n  DO {\n    moveTo(target: $card, to: energy, reveal: true)\n  }\n  -- First, and about the board rather than about any card — which is the order\n  -- `whyNotCharge` asks in, so the *first* requirement a player is owed is the\n  -- same requirement on both engines, a Leader in hand included.\n  REFUSE oncePerTurn(what: \"charge\") UNLESS NOT playerAttr(name: \"charged\")\n  -- 3-1-2: a Leader Card does not leave the Leader Area, so it is not a card\n  -- this move can be made about. Nothing puts one in a hand — 6-2-1-2 places it\n  -- before the first card is drawn — which is exactly why the refusal is\n  -- declared rather than assumed away: a rule that is never reached is still\n  -- the answer a player reaching for that card is owed.\n  REFUSE cardType(needs: \"a card that is not a Leader Card\") UNLESS count(FROM $card \"non-leader card\") >= 1\n  -- 20-14: \"your opponent can't place cards in their Energy Area.\" Last, which\n  -- is `whyNotCharge`'s order again — it asks the question first and the\n  -- prohibition second. The `forbidden` requirement's own fields (which card's\n  -- rule, how long it holds, what would let it through) are the board's and are\n  -- filled in by the interpreter, because a declaration cannot name a rule that\n  -- is not in the file.\n  REFUSE forbidden() UNLESS NOT forbidden(what: placeEnergy)\n  label: \"Charge\"\n  text: \"the turn player may place 1 card from their hand in their Energy Area, face up (7-2-11)\"\n\n-- 13-3: putting another copy of the Unison Card from hand under it, once a\n-- turn, is a player attribute too (`grewUnison`, `attributes.rules`) — the\n-- same shape issue #269 gave the charge, set by this action's own `DO` rather\n-- than by a phase boundary, because unlike the charge this move either\n-- happens or it does not; there is no window that closes on its own. The\n-- per-card gate needs \"a copy of the Unison Card in play\", which the filter\n-- grammar cannot name (another card's identity is not a fixed wording) —\n-- `sameCard` reads it as two selectors instead (`engine/script-schema.ts`).\nDEFINE ACTION growUnison                                                  -- §13-3\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.hand\n  BIND \"card\"\n  DO {\n    moveTo(target: $card, to: under, under: IN you.unison, reveal: true)\n    addMarker(target: IN you.unison, n: 1)\n    setPlayerAttr(name: \"grewUnison\")\n  }\n  -- Board-level first, `whyNotCharge`'s own order: nothing to grow at all is\n  -- answered before whether this turn's one growth is already spent, and only\n  -- then is a particular candidate wrong.\n  REFUSE oncePerTurn(what: \"grow a Unison\") UNLESS NOT playerAttr(name: \"grewUnison\")\n  REFUSE target(reason: \"no Unison Card in play to grow\") UNLESS count(IN you.unison) >= 1\n  REFUSE cardType(needs: \"a copy of the Unison Card in play\") UNLESS sameCard(a: FROM $card, b: IN you.unison)\n  label: \"Grow Unison\"\n  text: \"the turn player may, once per turn, place 1 copy of their Unison Card from their hand under it, adding 1 marker (13-3)\"\n\nDEFINE ACTION endMain                                                     -- §7-3-5\n  WHEN [main]\n  prompts: [main]\n  DO {}\n  label: \"End turn\"\n  text: \"the turn player ends their Main Phase, and with it the last phase they act in (7-3-5)\"\n\nDEFINE ACTION pass                                                        -- §7-3-4\n  WHEN [setup, charge, main]\n  prompts: [mulligan, charge, main]\n  DO {}\n  listed: false\n  label: \"Pass\"\n  text: \"take none of what the question offers, whatever it is (6-2-1-9-1, 7-2-11, 7-3-4)\"\n\n-- The one move that is not an answer to the question on the table: it is taken\n-- at any point in a game, including at a prompt that belongs to the other\n-- player, and no card may cause or replace it (0-1-3-4). So `WHEN` is every\n-- phase a game is still being played in, and `prompts:` is left out.\n--\n-- Its `DO` is empty because a game *ending* is not something the effect\n-- language can say — no op of `OP_SCHEMA` ends one — so the ending stays the\n-- interpreter's, the way the steps in `vm/flow.ts`'s `STEP_WORK` are, and this\n-- declaration is what decides the move may be taken at all. A `DO` written here\n-- would be a program `vm/index.ts` refuses by name rather than ignores.\n\nDEFINE ACTION concede                                                     -- §0-1-3-4\n  WHEN [setup, charge, main, mainEnd, end]\n  DO {}\n  listed: false\n  label: \"Concede\"\n  text: \"a player gives up the game, and their opponent wins immediately (0-1-3-4)\"\n\n-- ── playing a card (§5-5, §8-3-2, §13-2, §16-2) ────────────────────────────\n--\n-- Three paragraphs rather than one, because the shared `Action` union has\n-- three words: a client sends `play`, `playUnison` or `playZ`, and the\n-- declaration's **name is the action type** (`vm/actions.ts`). What they share\n-- is the `DO`: every one of them is the `play` op, which is 5-5-3's \"play this\n-- card\" — so a play a player declares and a play a skill makes are the same\n-- act, resolved in one place (`vm/play.ts`), and neither of them pends a\n-- trigger by name. The card arriving is `moved(asPlay: true)` and\n-- `triggers.rules` decides that this is `played`, `youPlayed` and\n-- `opponentPlayed`; its [Permanent]s stand because it is in an in-play area.\n--\n-- **20-14's prohibitions are read** (`forbidden()`), and each play below\n-- carries the gate: \"your opponent can't play Battle Cards\", \"this card can't\n-- be played from any area except by skills\". `bySkill: false` is the half of\n-- that wording a player's own declared play is — a play a *skill* makes is\n-- 5-5-3's, resolved by the `play` op and not by this paragraph.\n--\n-- One gate is still missing, and the language is what is missing: 22-39's\n-- [Unique] needs a filter for \"a card with the same name as *this* candidate\",\n-- which `FILTER_FIELDS` has no field for (the keyword's own body is #154's).\n--\n-- One ordering is deliberately not the legacy engine's, and is recorded rather\n-- than matched. A `REFUSE` is read **before** the price, which is where\n-- `whyNotPlay` sits for a Unison and for an X-cost card — but for a plain\n-- Battle Card `whyNotPlayFromHand` concatenates the price first, so on a board\n-- where the player is both short of energy *and* forbidden, that engine says\n-- \"1 short\" where this one says \"forbidden\". Saying a price about a move that\n-- is banned outright is the worse of the two answers, and the legacy engine\n-- already disagrees with itself about it across its own three branches\n-- (`verify/vm.ts` §21 asserts both, so neither drifts unnoticed).\n--\n-- The other half the price cannot settle is an **X cost**: 1-2-2-2 makes its\n-- value an answer to a question, and until issue #270 a candidate was a card\n-- and nothing else, so `costOf` was absent and `vm/costs.ts` refused such a\n-- card as `unread` rather than offering it free. `x: true` is the answer:\n-- one candidate per legal value of X, floored at the coloured requirement and\n-- ceilinged at what the player could pay, read generically off the price\n-- (`vm/costs.ts`'s `xValues`) rather than a branch per action. [Evolve],\n-- [Union], [Over Realm] and [Swap] are plays a keyword gates and are #157's.\n\nDEFINE ACTION play                                                        -- §8-3-2\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.hand \"battle card\"\n  BIND \"card\"\n  COST [energy]\n  x: true\n  DO {\n    play(target: $card)\n  }\n  REFUSE forbidden() UNLESS NOT forbidden(what: play, bySkill: false)\n  again: true\n  label: \"Play\"\n  text: \"the turn player pays a Battle Card's energy cost and places it in their Battle Area, active and revealed (8-3-2, 5-5)\"\n\n-- 13-2-3: a Unison Card arrives carrying the energy that was paid for it as\n-- markers, which is what `X` is in this program — the amount the move's price\n-- was settled at (`runProgram`). A Unison printed `X` lets its master choose\n-- how many markers to buy (13-2-2), the same `x: true` enumeration `play`\n-- above declares — `x` on the Action still comes off `price.energy`\n-- (`DECLARABLE_ACTIONS`'s `cardWithX` shape, unconditional since 13-2-3), so\n-- nothing about carrying it changed, only that a Unison whose printed cost is\n-- X now reaches a price to carry at all.\nDEFINE ACTION playUnison                                                  -- §13-2\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.hand \"unison card\"\n  BIND \"card\"\n  COST [energy]\n  x: true\n  xMin: 1                                                                 -- 13-2-2, 3-11-3: never zero markers\n  DO {\n    play(target: $card)\n    addMarker(target: $card, n: X)\n  }\n  REFUSE forbidden() UNLESS NOT forbidden(what: play, bySkill: false)\n  again: true\n  label: \"Play Unison\"\n  text: \"the turn player pays a Unison Card's cost and places it in their Unison Area with that many markers, sending the Unison already there to the Drop Area (13-2, 3-11-5)\"\n\n-- 16-2 and 17-2: a Z-card is played from the Z-Deck and pays a Z-Energy price\n-- as well as its energy cost, which is why this is the one move that names two\n-- prices — in that order, because that is the order the engine that has been\n-- playing charges them in and the order is what the oracle compares.\n--\n-- 6-1-4: a Z-Leader is not played at all, it arrives through [Z-Awaken]; and\n-- 18-2's Z-Unison is a Unison, so its markers are the `x` the paragraph above\n-- says a candidate cannot carry. Both are refused here as the cards this move\n-- is not about, which is the honest answer while it is about the other two.\nDEFINE ACTION playZ                                                       -- §16-2\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.zDeck \"Z-card\"\n  BIND \"card\"\n  COST [zEnergy, energy]\n  DO {\n    play(target: $card)\n  }\n  REFUSE cardType(needs: \"a Z-Battle Card or a Z-Extra Card\") UNLESS any([count(FROM $card \"Z-battle card\") >= 1, count(FROM $card \"Z-extra card\") >= 1])\n  REFUSE forbidden() UNLESS NOT forbidden(what: play, bySkill: false)\n  again: true\n  label: \"Play\"\n  text: \"the turn player pays a Z-card's Z-Energy price and its energy cost and places it in their Battle Area; a Z-Extra replaces the Z-Extras already there (16-2, 17-2-1-3)\"\n\n-- ── using a skill (§9-1-2, §4-3) ────────────────────────────────────────────\n--\n-- The one move whose candidate is **a line rather than a card**, which is what\n-- `skills:` says. A card prints up to nine of them, each with its own price,\n-- its own condition and its own once-per-turn ceiling, so one being on the menu\n-- says nothing at all about the other eight: §3.2 of\n-- `docs/arena-workflow-spec.md` counts one rejection per card per action type\n-- *except* an activation, which is one per line, and this declaration is where\n-- that exception is written down rather than special-cased.\n--\n-- Three things this paragraph does that no other does, and each is read off it:\n--\n--   `skills:`  the kinds it **offers**. A line of the same family and another\n--              window — an [Activate: Battle] skill at the Main Phase question\n--              — is still a candidate, and the answer it is owed is the\n--              `timing` requirement naming the window it belongs to. The\n--              window this move offers is the one its kinds share, so the\n--              battle paragraph Stage 6 writes needs no second table.\n--   `FOR`      where the lines are read from: the three in-play areas (9-1-3-1)\n--              and the hand, because 4-2 makes using an Extra Card from the\n--              hand how an Extra is played at all. A Battle Card's line in the\n--              hand is refused with the area it is valid in.\n--   `DO {}`    deliberately empty, and checked to be: the program an activation\n--              runs is the **record's** (`card_rules.ops`, carried on\n--              `Script.ops`), and a `DO` written once here could not be the\n--              program of nine different lines. `vm/activate.ts` queues that\n--              frame on the same interpreter a pended [Auto] runs on (#142),\n--              and the moment is a `skillActivated` the declarations in\n--              `triggers.rules` answer — nothing pends a trigger by name.\n--\n-- **The price is the record's too**, which is the 8 Sep 2026 precedent applied\n-- to a move: the orbs printed in front of the line and 13-4's marker cost are\n-- what `COST` below is charged, bound from the line rather than read off the\n-- card the way a play's price is (`vm/costs.ts`'s `BoundAmounts`). `text` is\n-- the half no engine charges itself, and it is named here so that a price this\n-- engine cannot read refuses the move with `unread` instead of offering it\n-- free. The order is `marker` before `energy` because that is the order the\n-- engine that has been playing charges them in, and the order is what the\n-- oracle compares.\n--\n-- **What it refuses and what it cannot.** Negation (9-1-5), the once-per-turn\n-- and [Limit X] count (22-44-3), [Bond X] and [Sparking X], 13-4's Unison Area\n-- and its one marker skill a turn, the condition 9-4 hoisted out of the price,\n-- the energy, an effect the compiler could not read, and 9-1-3-1's wrong area —\n-- in the order the legacy `whyNotActivate` asks them, so the first requirement\n-- is the same requirement on both engines. 20-14's prohibition is read too, and\n-- it is the one gate of this move that is **not** a `REFUSE` line here: the\n-- order is what matters and `whyNotActivate` asks it second, after the\n-- negation, where a declared `REFUSE` would run before everything. It is in\n-- `vm/activate.ts`'s gate list with the rest of them, at that position.\n--\n-- A keyword's own activation — [Awaken], [Evolve], [Union], [Over Realm],\n-- [Swap], [Arrival], [Successor], [Aegis], [Rejuvenate], [Overlord], [Field],\n-- [Z-Awaken] — is a `DEFINE KEYWORD` hook body and is Stage 7's (#153–#157);\n-- such a line is refused `unread` rather than left off both lists, because a\n-- player reaching for it is owed an answer. An action price (4-3-3) is\n-- refused the same way and for the same reason 22-39's [Unique] is unread:\n-- the value or the identity is not a fixed wording. An X price (20-5) is\n-- issue #270's `x: true` in principle — the price is a skill line's own\n-- (`BoundAmounts`), not a card attribute `xValues` reads, so wiring it up is\n-- separate plumbing in `activate`'s own candidate builder and is not done\n-- here; such a line stays refused `unread`, honestly rather than by\n-- omission. [Counter] windows are Stage 6's (#150), and no phase here asks\n-- one.\n\nDEFINE ACTION activate                                                    -- §9-1-2\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.hand|leader|unison|battle\n  BIND \"card\"\n  skills: [\"activate:main\", \"activate:main/battle\"]\n  COST [marker, energy, text]\n  DO {}\n  again: true\n  label: \"Activate\"\n  text: \"a player uses one of a card's [Activate] skills, paying the price printed in front of it; the skill then resolves (9-1-2, 4-3-3)\"\n",
  "attributes.rules": "-- What a card and a player have, as declarations.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §2 is the parts of a card, §1-2\n-- energy costs (total and specified), §1-9 the front and back sides, §1-14\n-- energy markers, §9-9-1 the order continuous effects are applied in, §20-1\n-- names a skill gives a card in all areas and §20-21 increasing or reducing\n-- an energy cost.\n--\n-- `printed: true` means the value is read off the card itself — \"the\n-- information specified on a card itself\", which §9-9-1-1 makes the base\n-- reference for everything below it. `layers:` is the order the game then\n-- applies to reach the value the rules actually use, §9-9-1 throughout:\n--   printed   the face value (9-9-1-1)\n--   rewrite   every continuous effect except those that rewrite a number\n--             (9-9-1-2)\n--   numeric   the continuous effects that rewrite a number (9-9-1-3)\n-- A cost has its own two layers because a reduction is not a rewrite of the\n-- printed cost but a discount on the price being paid (20-21): `reduction`\n-- is the flat one, `specified` the coloured one, and they move apart —\n-- `docs/arena-history-lessons.md`, 8 Sep 2026 and the owner's BT19-039\n-- ruling of 9 Sep 2026. The two therefore sit on *different* attributes:\n-- `reduction` on both halves of a price, since taking 1 off a total takes one\n-- orb with it (20-21-2), and `specified` on the coloured half alone, which is\n-- what \"moves the total nothing\" means when it is written down.\n--\n-- Where an attribute's real domain cannot be said in this grammar — `value:`\n-- knows five shapes and no enum, no union and no map — the text says what the\n-- domain is instead, and the history entry of 12 Sep 2026 records the gap\n-- rather than the file stretching to cover it.\n\n-- ── printed on the card (§2) ───────────────────────────────────────────────\n\nDEFINE ATTRIBUTE id                                                       -- §2-14\n  of: card\n  value: string\n  printed: true\n  text: \"the card number, which is what a copy limit and every reference to a card counts by (2-14, 6-1-5-1)\"\n\nDEFINE ATTRIBUTE name                                                     -- §2-3\n  of: card\n  value: string\n  printed: true\n  text: \"the card name (2-3)\"\n\nDEFINE ATTRIBUTE type                                                     -- §2-1\n  of: card\n  value: string\n  printed: true\n  text: \"the card type, one of LEADER, BATTLE, EXTRA, UNISON, Z-LEADER, Z-BATTLE, Z-EXTRA, Z-UNISON and TOKEN (2-1, 10 to 19)\"\n\nDEFINE ATTRIBUTE colors                                                   -- §2-2\n  of: card\n  value: colors\n  printed: true\n  text: \"the card's colors: red, blue, green, yellow, black, white, or none of them (1-8, 2-2)\"\n\nDEFINE ATTRIBUTE energyCost                                               -- §2-5\n  of: card\n  value: number\n  printed: true\n  text: \"the total cost of playing the card from hand; an X cost is a number its master chooses when it is paid and zero at every other time (1-2-2, 1-2-2-2)\"\n\nDEFINE ATTRIBUTE specifiedCost                                            -- §1-2-3\n  of: card\n  value: colors\n  printed: true\n  layers: [printed, reduction, specified]\n  text: \"the coloured orbs of the energy cost, one entry per orb, that must be matched in colour when the cost is paid (1-2-3, 5-3); a flat reduction takes an orb off with each energy it takes off the total (20-21-2), and the `specified` layer is the half that relaxes or tightens the colours alone without moving the total at all\"\n\nDEFINE ATTRIBUTE zEnergyCost                                             -- §2-6\n  of: card\n  value: number\n  printed: true\n  text: \"the Z-Energy cost of playing the card from the Z-Deck (1-4, 2-6)\"\n\nDEFINE ATTRIBUTE power                                                    -- §2-7\n  of: card\n  value: number\n  printed: true\n  layers: [printed, rewrite, numeric]\n  text: \"the number a battle is decided by (2-7, 8-4); combo power is added to it only in the Damage Step (5-7)\"\n\nDEFINE ATTRIBUTE comboCost                                                -- §2-9\n  of: card\n  value: number\n  printed: true\n  text: \"the energy paid to use the card in a combo (2-9, 5-6)\"\n\nDEFINE ATTRIBUTE comboPower                                               -- §2-8\n  of: card\n  value: number\n  printed: true\n  layers: [printed, rewrite, numeric]\n  text: \"the power the card adds when it is used in a combo (2-8, 5-7)\"\n\nDEFINE ATTRIBUTE characters                                               -- §2-10\n  of: card\n  value: strings\n  printed: true\n  text: \"the character names the card carries, written in angle brackets (2-10)\"\n\nDEFINE ATTRIBUTE traits                                                   -- §2-11\n  of: card\n  value: strings\n  printed: true\n  text: \"the special traits the card carries, written in double angle brackets (2-11)\"\n\nDEFINE ATTRIBUTE skill                                                    -- §2-4\n  of: card\n  value: string\n  printed: true\n  text: \"the card's text box, which is every skill it has before any is gained or negated (2-4, 1-5)\"\n\nDEFINE ATTRIBUTE back                                                     -- §1-9\n  of: card\n  value: boolean\n  printed: true\n  text: \"whether the card has a back side to turn to — a Leader's awakened face, or a Z-Leader's single face (1-9). What is printed on that face is a face of its own, which this grammar has no kind for; see the history entry of 12 Sep 2026\"\n\nDEFINE ATTRIBUTE alsoNames                                                -- §20-1\n  of: card\n  value: strings\n  printed: false\n  text: \"the card names a skill gave this card in all areas; it answers to these as well as to its printed name, never instead of it (20-1)\"\n\n-- ── what the board makes of them (§9-9-1, §20-21) ──────────────────────────\n\nDEFINE ATTRIBUTE costOf                                                   -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction]\n  text: \"the total price of playing this card as it stands: the printed total cost, less every cost reduction in force, and never less than zero (20-21-1, 20-21-2). The coloured half of the same price is `specifiedCost`, which carries the `specified` layer, because a sentence that relaxes which colours are demanded moves the total nothing at all — the owner's BT19-039 ruling of 9 Sep 2026\"\n\nDEFINE ATTRIBUTE comboCostOf                                              -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction]\n  text: \"the combo cost as it stands, after every reducer in force, and never less than zero (5-7-3, 20-21-2)\"\n\nDEFINE ATTRIBUTE zEnergyCostOf                                            -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction]\n  text: \"the Z-Energy cost as it stands, after every reducer in force, and never less than zero (5-4, 20-21-2)\"\n\n-- ── what a player has (§1-14) ──────────────────────────────────────────────\n\nDEFINE ATTRIBUTE energyMarkers                                            -- §1-14\n  of: player\n  value: number\n  printed: false\n  text: \"the energy markers in a player's Energy Area: each pays one energy of the Leader's colour, and neither is a card nor is energy (1-14-1, 1-14-2, 1-14-3)\"\n\n-- These two are facts about a player rather than about the board, which is\n-- the gap #145's charge and #157's growUnison were left standing on: 7-2-11's\n-- one charge and 13-3's one Unison growth are each a player having \"already\n-- had\" one this turn, and until now the language had no word for that,\n-- letting the charge's `REFUSE` only borrow a proxy word instead\n-- (`asking(prompt: charge)`, which said which question was on the table\n-- rather than the fact itself). `reset: turnStart` is the ceiling, read by\n-- `vm/flow.ts`'s `endTurn` off the declaration rather than picked out of it\n-- by name — the same promise `LIMIT n` on a step makes for a repeat (issue\n-- #269).\n\nDEFINE ATTRIBUTE charged                                                  -- §7-2-11\n  of: player\n  value: boolean\n  printed: false\n  reset: turnStart\n  text: \"whether this player has had their one charge this turn (7-2-11); true from the moment the Charge Phase's own question is answered, charging or not, since that is the only opportunity this engine offers one at\"\n\nDEFINE ATTRIBUTE grewUnison                                               -- §13-3\n  of: player\n  value: boolean\n  printed: false\n  reset: turnStart\n  text: \"whether this player has already grown their Unison Card this turn (13-3); set the moment growUnison resolves\"\n",
  "costs.rules": "-- What a move costs, as declarations rather than as branches of one search.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §5-3 paying an energy cost and\n-- §8-3-2-3 doing it in the Main Phase, §1-2-3 the specified (coloured) half of\n-- a cost, §1-14-2 energy markers standing in for energy of the Leader's\n-- colour, §3-8-2 the player's free choice of which energy to rest, §13-4 a\n-- Unison's marker cost, §20-5 an X price, §20-19 a card rested in the Energy\n-- Area's place, §21-3 life as a price, and §22-30 [Warrior of Universe 7].\n--\n-- In the legacy engine payment is one function, `planPayment` in\n-- `engine/state.ts`, with a branch inside it for each of those: the coloured\n-- orbs, the either-orbs, X, the cards that may stand in for energy, and\n-- [Warrior of Universe 7] clearing the colours outright. It plays this game\n-- correctly and it can only ever play this game — a second game with a\n-- different resource has nowhere to say so. Here each is a `DEFINE COST`, and\n-- `vm/costs.ts` is one planner over the **declared** kinds (#148).\n--\n-- Two lines carry the whole of what an interpreter needs to charge a price it\n-- has never seen:\n--\n--   `consumes:`  the resource it takes — `energy`, `markers`, `life`, `mode`,\n--                `cards`, or `unreadable` for the half of a printed price no\n--                engine can charge itself. The planner switches on this word\n--                and never on the declaration's *name*, so a second game's\n--                `DEFINE COST mana / consumes: energy` is charged by the same\n--                search this file's `energy` is.\n--   `amount:`    the **card attribute** the price's amount is read off, when\n--                the move asking for it names a card (§20-21). `ACTION play\n--                COST [energy]` passes no arguments, so the number comes from\n--                the card being paid for, and this line is where the game says\n--                which number that is. It names the *derived* attribute\n--                (`costOf`, never `energyCost`), so every reduction in force\n--                reaches a play's price through the declared `layers:` rather\n--                than through a second path.\n--   `asks:`      how the payment puts its question (§3-8-2). `choice` is a\n--                price the payer is asked about whenever more than one\n--                genuinely different way to pay it exists — which is the\n--                `payCost` prompt the board already answers; `nothing` is a\n--                price with only ever one way to pay, which is settled without\n--                a question.\n--\n-- The `DO` program says two things at once, and both are read: its **target**\n-- is the pool the price is paid out of (the active cards in your Energy Area,\n-- the cards in your life), and the **op** is what paying does to what was\n-- taken from it. How *many* is the price's own amount and is never in the\n-- program — an action asks for a price by name and the amount comes off the\n-- card being paid for.\n--\n-- Two gaps are written here rather than papered over. `TAKES` names what each\n-- price is given, but `ACTION ... COST [energy]` passes no arguments, so where\n-- the values come from is the *thing being paid for*: a price paid for a card\n-- reads its amount off the card through `amount:` above, and a price paid for a\n-- **skill line** has it bound in by the interpreter that knows which line it is\n-- (#147, `vm/costs.ts`'s `BoundAmounts`) — which is where `marker` and `life`\n-- get their numbers and `text` gets bound away on a skill whose whole cost is\n-- orbs. `payWith` still has nothing to bind it anywhere and is refused by name.\n-- And an **either-orb** (\"{Red/Blue}\", one orb payable with any one of the\n-- listed colours, §22-13) has no parameter type that can name it: `colors` is a\n-- flat list and the language knows no list of alternatives. The planner reads them off the price\n-- and charges them exactly; the parameter list below cannot say so, the way\n-- `attributes.rules` cannot say what is printed on a card's back side.\n\nDEFINE COST energy                                                        -- §5-3\n  TAKES (total: amount, orbs: colors, x: amount)\n  consumes: energy\n  amount: \"costOf\"\n  asks: choice\n  DO {\n    switchMode(target: IN you.energy active, mode: rest)\n  }\n  text: \"the price is paid by switching that many active cards in your Energy Area to Rest Mode, the coloured orbs matched in colour; an energy marker pays one energy of your Leader's colour in a card's place (5-3-3, 1-2-3, 1-14-2)\"\n\n-- The other half of a Z-card's price (§5-4). It is a `cards` price like\n-- `payWith` below and the planner tells the two apart the way it tells any two\n-- prices apart — by reading the `DO`, never the name: this one's target names\n-- a **place** (`IN you.zEnergy`), so the cards come out of that pool and go\n-- where the op says; `payWith`'s names cards the price was handed, so they are\n-- rested where they stand. 5-4-3: the Z-Energy is spent, not rested — the\n-- cards are placed in the Drop Area — which is why the op is a move.\nDEFINE COST zEnergy                                                       -- §5-4\n  TAKES (n: amount)\n  consumes: cards\n  amount: \"zEnergyCostOf\"\n  asks: nothing\n  DO {\n    moveTo(target: IN you.zEnergy, to: drop)\n  }\n  text: \"a Z-card's Z-Energy price: that many cards are placed from the Z-Energy Area in the Drop Area, on top of the card's energy cost (5-4, 16-2-1)\"\n\nDEFINE COST marker                                                        -- §13-4\n  TAKES (n: amount)\n  consumes: markers\n  asks: nothing\n  DO {\n    addMarker(target: [self], n: $n)\n  }\n  text: \"the price is paid with the markers on the card whose skill is being used: a negative number removes that many, and the card may use no further marker skill this turn (13-4, 1-11)\"\n\nDEFINE COST life                                                          -- §21-3\n  TAKES (n: amount)\n  consumes: life\n  asks: nothing\n  DO {\n    moveTo(target: IN you.life, to: drop)\n  }\n  text: \"the price is paid by placing that many cards from your life in your Drop Area (21-3)\"\n\nDEFINE COST rest                                                          -- §8-4-1\n  TAKES ()\n  consumes: mode\n  asks: nothing\n  DO {\n    switchMode(target: [self], mode: rest)\n  }\n  text: \"the price is paid by switching the card itself to Rest Mode, which a card already in Rest Mode cannot do (1-10-1)\"\n\nDEFINE COST payWith                                                       -- §20-19\n  TAKES (cards: selector)\n  consumes: cards\n  asks: choice\n  DO {\n    switchMode(target: FROM $cards, mode: rest)\n  }\n  text: \"cards outside the Energy Area that this price may be paid with instead, each rested where it stands and counting as energy of the colours the price says (20-19)\"\n\n-- The price the engine does not charge, and the reason it is a declaration at\n-- all: a move whose price has no `DEFINE COST` would be offered for free, and\n-- a move whose price is *declared unreadable* is refused with an `unread`\n-- requirement naming the card — the same answer the legacy engine gives for a\n-- skill whose cost the compiler could not read.\nDEFINE COST text                                                          -- §4-3-3\n  TAKES (printed: string)\n  consumes: unreadable\n  asks: nothing\n  DO {}\n  text: \"the price as printed, kept for the part no engine can charge itself; a move that asks for it is refused rather than offered free (4-3-3)\"\n",
  "game.rules": "-- The Dragon Ball Super Card Game itself: how a player starts, what a turn is\n-- made of, and how the game ends.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §0-1-3 ending the game, §6-1 the\n-- Leader Card and the decks, §6-2 pre-game preparations, §7-1 the turn,\n-- §7-2 the Charge Phase, §7-3 the Main Phase, §7-4 the End Phase.\n--\n-- Three things the manual says here that the grammar has no field for are\n-- left out rather than written wrongly, and each is recorded in the history\n-- entry of 12 Sep 2026:\n--   * the deck is 50 **to 60** cards (6-1-3) and a Z-Deck is **up to** 10\n--     (6-1-4) — `deck:` and `zDeck:` are one number each, so they are read\n--     below as the deck's minimum and the Z-Deck's maximum;\n--   * a deck may hold up to 4 copies of a card number (6-1-5-1) — there is no\n--     field for a copy limit;\n--   * only the player who goes **second** places an energy marker (6-2-1-11)\n--     — `startMarkers:` is one number for both players, so it is left out and\n--     the setup step below is where that rule is said.\n\nDEFINE GAME dbs                                                           -- §6-1\n  title: \"Dragon Ball Super Card Game\"\n  players: 2\n  deck: 50\n  zDeck: 10\n  hand: 6\n  life: 8\n  mulligan: true\n  firstPlayerDraws: false\n  phases: [charge, main, mainEnd, end]\n  setupPhase: \"setup\"\n  overPhase: \"over\"\n\n-- ── the phases ────────────────────────────────────────────────────────────\n--\n-- A turn is three phases, each made of steps, and a phase or a step exists\n-- even when nothing happens in it (7-1-1). `setup` and `over` are not phases\n-- of a turn: they are the pre-game procedure (6-2) and the end of the game\n-- (0-1-3), which this engine runs as phases of their own and which is why\n-- `DEFINE GAME`'s `phases:` above lists four names and not six. They are\n-- named instead by `setupPhase:` and `overPhase:`, so the flow runner knows\n-- where a game begins and where it comes to rest without knowing either word\n-- (#140).\n--\n-- `announce:` is whether entering a phase is a moment of its own in the log —\n-- the beat the board narrates. Three of the six are announced, which is what\n-- the engine that has been playing announces: the Main Phase End Step passes\n-- inside the Main Phase as far as a player is concerned (7-3-5), and neither\n-- the pre-game procedure nor the finished game is a phase of a turn at all.\n--\n-- The manual makes the Main Phase End Step a step of the Main Phase\n-- (7-3-5); this engine has run it as a phase of its own since before the\n-- rules language existed, so it is declared as one here. The history entry of\n-- 12 Sep 2026 records the difference.\n--\n-- `actions:` is left off every phase: the moves a player may declare (7-3-4)\n-- are `DEFINE ACTION`s, and the loader refuses a phase naming one that\n-- nothing declares. They arrive with `play.rules`.\n\nDEFINE PHASE setup                                                        -- §6-2\n  steps: [setupPresent, setupLeader, setupLeaderPending, setupFirstPlayer, setupShuffle, setupZDeck, setupHand, setupMulligan, setupLife, setupEnergyMarker, setupStart]\n  auto: false\n  announce: false\n  text: \"the pre-game procedure, before the first turn: leaders down, first player chosen, hands drawn and life set out (6-2-1)\"\n\nDEFINE PHASE charge                                                       -- §7-2\n  steps: [chargeTurnEffects, chargeContinuousEnd, chargePending, chargeActivate, chargeDraw, chargeEnergy]\n  auto: false\n  announce: true\n  text: \"the rules processing at the start of a turn, with a checkpoint after each step (7-2-1, 7-2-6, 7-2-8, 7-2-10, 7-2-12)\"\n\nDEFINE PHASE main                                                         -- §7-3\n  steps: [mainPending, mainActions]\n  auto: false\n  announce: true\n  text: \"the phase the turn player takes their moves in, returning to a checkpoint after each one (7-3-1, 7-3-4)\"\n\nDEFINE PHASE mainEnd                                                      -- §7-3-5\n  steps: [mainEndPending, mainEndEffects]\n  auto: true\n  announce: false\n  text: \"the Main Phase End Step, which the manual counts as a step of the Main Phase and this engine runs as a phase (7-3-5)\"\n\nDEFINE PHASE end                                                          -- §7-4\n  steps: [endPending, endRepeat, endEffects, endTurn]\n  auto: true\n  announce: true\n  text: \"the end of the turn: what answers to it is made pending, what lasted for the turn ends, and the other player becomes the turn player (7-4-1, 7-4-7)\"\n\nDEFINE PHASE over                                                         -- §0-1-3\n  steps: [gameEnd]\n  auto: true\n  announce: false\n  text: \"the game is over, which is not a phase of a turn: a player has lost and nothing further is played (0-1-3)\"\n\n-- ── setup (§6-2-1) ────────────────────────────────────────────────────────\n\nDEFINE STEP setupPresent                                                  -- §6-2-1-1\n  phase: \"setup\"\n  optional: false\n  text: \"each player presents the Leader Card, deck and Z-Deck they will use, which must meet the deck construction rules (6-2-1-1, 6-1)\"\n\nDEFINE STEP setupLeader                                                   -- §6-2-1-2\n  phase: \"setup\"\n  optional: false\n  text: \"each player places their Leader Card front side up in their Leader Area (6-2-1-2)\"\n\nDEFINE STEP setupLeaderPending                                            -- §6-2-1-3\n  phase: \"setup\"\n  optional: false\n  text: \"trigger conditions for \\\"when this card is placed in a Leader Area\\\" skills enter pending (6-2-1-3)\"\n\nDEFINE STEP setupFirstPlayer                                              -- §6-2-1-4\n  phase: \"setup\"\n  optional: false\n  prompt: \"chooseFirst\"\n  text: \"by a random method one player is chosen, and that player chooses who goes first (6-2-1-4, 6-2-1-5)\"\n\nDEFINE STEP setupShuffle                                                  -- §6-2-1-7\n  phase: \"setup\"\n  optional: false\n  text: \"each player shuffles their deck and places it face down in their Deck Area (6-2-1-7)\"\n\nDEFINE STEP setupZDeck                                                    -- §6-2-1-8\n  phase: \"setup\"\n  optional: false\n  text: \"each player places their Z-Deck face down in their Z-Deck Area (6-2-1-8)\"\n\nDEFINE STEP setupHand                                                     -- §6-2-1-9\n  phase: \"setup\"\n  optional: false\n  text: \"each player draws 6 cards from their deck as their opening hand (6-2-1-9)\"\n\nDEFINE STEP setupMulligan                                                 -- §6-2-1-9-1\n  phase: \"setup\"\n  optional: true\n  prompt: \"mulligan\"\n  text: \"beginning with the starting player, each player may return their hand to their deck, shuffle, and draw 6 new cards — once (6-2-1-9, 6-2-1-9-1)\"\n\nDEFINE STEP setupLife                                                     -- §6-2-1-10\n  phase: \"setup\"\n  optional: false\n  text: \"each player places the top 8 cards of their deck face down in their Life Area (6-2-1-10)\"\n\nDEFINE STEP setupEnergyMarker                                             -- §6-2-1-11\n  phase: \"setup\"\n  optional: false\n  text: \"the player who goes second places 1 energy marker in their Energy Area, and the player who goes first places none (6-2-1-11)\"\n\nDEFINE STEP setupStart                                                    -- §6-2-1-12\n  phase: \"setup\"\n  optional: false\n  text: \"the first player begins the game and starts their turn (6-2-1-12)\"\n\n-- ── the Charge Phase (§7-2) ───────────────────────────────────────────────\n\nDEFINE STEP chargeTurnEffects                                             -- §7-2-2\n  phase: \"charge\"\n  optional: false\n  text: \"effects that last \\\"for the turn\\\" occur, for the turn player and then for the non-turn player (7-2-2, 7-2-3)\"\n\nDEFINE STEP chargeContinuousEnd                                           -- §7-2-4\n  phase: \"charge\"\n  optional: false\n  text: \"continuous effects that last \\\"until the start of your opponent's turn\\\" end (7-2-4)\"\n\nDEFINE STEP chargePending                                                 -- §7-2-5\n  phase: \"charge\"\n  optional: false\n  text: \"effects that read \\\"at the beginning of the turn\\\" and \\\"at the beginning of the Charge Phase\\\" enter pending (7-2-5)\"\n\nDEFINE STEP chargeActivate                                                -- §7-2-7\n  phase: \"charge\"\n  optional: false\n  text: \"each player switches every card in their Leader, Battle, Energy and Unison Areas that is in Rest Mode to Active Mode (7-2-7)\"\n\nDEFINE STEP chargeDraw                                                    -- §7-2-9\n  phase: \"charge\"\n  optional: false\n  text: \"the turn player draws 1 card, except the player who goes first, on their first turn (7-2-9, 7-2-9-1)\"\n\nDEFINE STEP chargeEnergy                                                  -- §7-2-11\n  phase: \"charge\"\n  optional: true\n  prompt: \"charge\"\n  text: \"the turn player may place 1 card from their hand in their Energy Area (7-2-11)\"\n\n-- ── the Main Phase (§7-3) ─────────────────────────────────────────────────\n\nDEFINE STEP mainPending                                                   -- §7-3-2\n  phase: \"main\"\n  optional: false\n  text: \"effects that read \\\"at the beginning of the Main Phase\\\" enter pending (7-3-2)\"\n\nDEFINE STEP mainActions                                                   -- §7-3-4\n  phase: \"main\"\n  optional: false\n  prompt: \"main\"\n  text: \"the turn player is granted a free timing: play a card, activate an [Activate : Main] skill, grow a Unison Card, attack, or end the Main Phase (7-3-4)\"\n\nDEFINE STEP mainEndPending                                                -- §7-3-5-1-1\n  phase: \"mainEnd\"\n  optional: false\n  text: \"skills that read \\\"at the end of the Main Phase\\\" enter pending (7-3-5-1-1)\"\n\nDEFINE STEP mainEndEffects                                                -- §7-3-5-1-3\n  phase: \"mainEnd\"\n  optional: false\n  text: \"effects that last \\\"for the Main Phase\\\" end, for the turn player and then for the non-turn player (7-3-5-1-3, 7-3-5-1-4)\"\n\n-- ── the End Phase (§7-4) ──────────────────────────────────────────────────\n\nDEFINE STEP endPending                                                    -- §7-4-2\n  phase: \"end\"\n  optional: false\n  text: \"skills that read \\\"at the end of the turn\\\" enter pending, except any [Auto] whose trigger condition was already fulfilled this turn (7-4-2)\"\n\nDEFINE STEP endRepeat                                                     -- §7-4-4\n  phase: \"end\"\n  optional: false\n  LIMIT 5\n  text: \"if an \\\"at the end of the turn\\\" [Auto] has still not been fulfilled this turn, the End Phase is carried out again from the beginning (7-4-4)\"\n\nDEFINE STEP endEffects                                                    -- §7-4-5\n  phase: \"end\"\n  optional: false\n  text: \"every effect that lasts \\\"for the turn\\\" or \\\"until the end of the turn\\\" ends, for the turn player and then for the non-turn player (7-4-5, 7-4-6)\"\n\nDEFINE STEP endTurn                                                       -- §7-4-7\n  phase: \"end\"\n  optional: false\n  text: \"the turn ends, the non-turn player becomes the turn player, and play proceeds to the next turn's Charge Phase (7-4-7)\"\n\n-- ── the game is over (§0-1-3) ─────────────────────────────────────────────\n\nDEFINE STEP gameEnd                                                       -- §0-1-3\n  phase: \"over\"\n  optional: false\n  prompt: \"gameOver\"\n  text: \"a player has fulfilled a defeat condition and the game has ended (0-1-3, 0-1-3-1)\"\n\n-- ── how the game ends (§0-1-3) ────────────────────────────────────────────\n--\n-- The two defeat conditions of 0-1-3-2. A player who fulfils either loses\n-- immediately (0-1-3-1), and a player whose opponent loses while they did not\n-- wins (0-1-3).\n--\n-- Two more ways the manual ends a game are not declared, because a condition\n-- in this language reads the board and neither of these is on it: conceding\n-- (0-1-3-4), which is a player's act and which no card may cause or replace\n-- (0-2-2-1), and a card that makes a player win or lose as its effect\n-- resolves (0-1-3-5). Nor can the draw of 0-1-3-3 be said, since \"both\n-- players fulfil a defeat condition simultaneously\" is a statement about the\n-- other declarations rather than about the board. All three are in the\n-- history entry of 12 Sep 2026.\n\nDEFINE WIN lifeOut                                                        -- §0-1-3-2\n  IF count(IN you.life) <= 0\n  result: lose\n  who: you\n  text: \"there are no cards in your Life Area (0-1-3-2)\"\n\nDEFINE WIN deckOut                                                        -- §0-1-3-2\n  IF count(IN you.deck) <= 0\n  result: lose\n  who: you\n  text: \"there are no cards in your Deck Area (0-1-3-2)\"\n",
  "keywords.rules": "-- Every keyword skill KEYWORD_NAMES (engine/script-schema.ts) lists, in that\n-- order. TAKES is the arity KeywordSkill (engine/types.ts) carries and\n-- keywordOf (engine/cards.ts) reads back; scripts/verify/rulesets.ts checks\n-- both against this file. text: is the glossary's meaning line, verbatim\n-- (src/lib/arena/glossary.ts), so /arena/rules/keywords can render it from\n-- here once Stage 8 (#159) swaps the reader. No HOOK bodies yet — that is\n-- Stage 7 (#153-#157); a keyword's own moments stay the engine's until then.\n\n-- 22-2\nDEFINE KEYWORD Awaken\n  TAKES (surge: boolean)\n  text: \"A Leader's own skill. Meet the printed condition, pay the cost, carry out the effect, then flip the Leader onto its awakened side. [Awaken: Surge] is the same skill under another name, and card text saying “[Awaken] skills” means both.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-25\nDEFINE KEYWORD Wish\n  TAKES ()\n  text: \"The same shape as [Awaken]: a condition, an effect, and then the Leader is flipped over.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-3\nDEFINE KEYWORD Field\n  TAKES ()\n  text: \"An Extra Card that stays on the table in Active Mode instead of going to the Drop Area. Its other skills work from there, and playing another [Field] Extra drops the one already out.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-4\nDEFINE KEYWORD Blocker\n  TAKES ()\n  text: \"When one of your other cards is attacked, switch this card to Rest Mode to become the guard card instead.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-6\nDEFINE KEYWORD Critical\n  TAKES ()\n  text: \"Life damage this card deals by attacking goes to the opponent's Drop Area instead of their hand.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-7\nDEFINE KEYWORD Strike\n  TAKES (x: number)\n  text: \"When this card would deal less than X life damage by attacking, it deals X instead — 2, 3 or 4.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-8\nDEFINE KEYWORD Attack\n  TAKES (x: number)\n  text: \"When this card attacks, it switches back to Active Mode at the end of the battle — X−1 times a turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-9\nDEFINE KEYWORD Revenge\n  TAKES ()\n  text: \"When this card becomes the guard card, KO the attacking card at the end of the battle.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-12\nDEFINE KEYWORD Indestructible\n  TAKES ()\n  text: \"This card can't be KO'd or moved out of your Battle Area by the opponent's skills or as a result of battle.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-16\nDEFINE KEYWORD Barrier\n  TAKES ()\n  text: \"This card can't be chosen by the skills of cards your opponent masters.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-20\nDEFINE KEYWORD Deflect\n  TAKES ()\n  text: \"This card isn't affected by your opponent's [Counter: Play] skills. Valid in every area.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-39\nDEFINE KEYWORD Unique\n  TAKES ()\n  text: \"While a card with [Unique] is in play you can't play another card with the same name. If two are somehow in play at once, their master keeps one and drops the rest.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-40\nDEFINE KEYWORD Servant\n  TAKES ()\n  text: \"+10000 power, and the card does not switch to Active Mode during its master's Charge Phase.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-31\nDEFINE KEYWORD \"Energy-Exhaust\"\n  TAKES ()\n  text: \"When this card is placed in an Energy Area, it arrives in Rest Mode. Valid in every area.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-18\nDEFINE KEYWORD \"Victory Strike\"\n  TAKES ()\n  text: \"Deal life damage by attacking with this card and you win the game.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-19\nDEFINE KEYWORD \"Warrior of Universe 7\"\n  TAKES ()\n  text: \"Treat your ≪Universe 7≫ cards in every area as having no specified cost — the coloured part of a play's price.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-14\nDEFINE KEYWORD Ultimate\n  TAKES ()\n  text: \"A deck may hold at most one card with [Ultimate], and a card with it that leaves play is removed from the game rather than going anywhere else.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-17\nDEFINE KEYWORD \"Super Combo\"\n  TAKES ()\n  text: \"A deck may hold at most four cards with [Super Combo], counted across all of them.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-28\nDEFINE KEYWORD \"Dragon Ball\"\n  TAKES ()\n  text: \"As many copies of a [Dragon Ball] card as you like, as long as no more than seven [Dragon Ball] cards are in the deck all told.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-24\nDEFINE KEYWORD Wormhole\n  TAKES ()\n  text: \"[Over Realm] and [Dark Over Realm] may be activated twice a turn between them instead of once.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-37\nDEFINE KEYWORD Invoker\n  TAKES ()\n  text: \"A Red/Blue multicolour Extra Card in your hand may be activated by switching one active Red/Blue multicolour energy to Rest Mode instead of paying its energy cost.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-35\nDEFINE KEYWORD Heroic\n  TAKES ()\n  text: \"When you play another card with [Heroic], draw 1 card; the skill is then negated on this card for the rest of the turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-36\nDEFINE KEYWORD Villainous\n  TAKES ()\n  text: \"When you play another card with [Villainous], your opponent chooses a card in their hand and drops it; the skill is then negated for the rest of the turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-33\nDEFINE KEYWORD Offering\n  TAKES ()\n  text: \"When this Battle Card is played, your opponent may put one of their life cards in their Drop Area. If they don't, you draw 2 cards.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-5\nDEFINE KEYWORD Evolve\n  TAKES (variant: string)\n  text: \"From hand: pay the cost, choose one of your Battle Cards matching the printed description, and play this card on top of it. [Xeno-Evolve] sends the chosen card to the Warp instead of stacking onto it.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-13\nDEFINE KEYWORD Union\n  TAKES (variant: string)\n  text: \"Three ways to play a Battle Card by naming characters. Fusion drops one of each named character from your hand, both of equal power. Potara plays this card on top of two named characters in your Battle Area. Absorb is activated from the Battle Area, and its text says which card is played onto this one.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-15, 22-23\nDEFINE KEYWORD \"Over Realm\"\n  TAKES (x: number, dark: boolean)\n  text: \"With X or more cards in your Drop Area — X or more black cards, for the dark one — send your whole Drop Area to the Warp as the cost and play this card from hand. The two share one activation a turn. A card played with [Over Realm] goes to the Warp at the end of that turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-22\nDEFINE KEYWORD Swap\n  TAKES (x: number)\n  text: \"Return this Battle Card to your hand and play a named Battle Card with an energy cost of X from your hand in its place.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-29\nDEFINE KEYWORD Arrival\n  TAKES (colors: colors)\n  text: \"During a battle, when the original colours of the Battle Cards in your Combo Area cover every colour named, pay the cost and play this card from hand.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-30\nDEFINE KEYWORD Aegis\n  TAKES (colors: colors)\n  text: \"In the Defense Step of your opponent's turn, drop cards from your hand covering the named colours to switch up to two of your energy from Rest to Active Mode.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-32\nDEFINE KEYWORD Alliance\n  TAKES (colors: colors)\n  text: \"When this card attacks, you may switch one or more of your other Battle Cards of the named colours to Rest Mode as the cost of the printed effect.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-34\nDEFINE KEYWORD Revive\n  TAKES (colors: colors)\n  text: \"When this Battle Card is KO'd, drop cards from hand whose original colours cover both named colours to play it back from your Drop Area. [Revive] is then negated on it for the turn.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-38\nDEFINE KEYWORD Successor\n  TAKES ()\n  text: \"Drop any number of mono-green, mono-yellow or Green/Yellow Battle Cards from your Battle Area whose energy costs add up to exactly this card's printed cost, and play it from hand.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-41\nDEFINE KEYWORD Overlord\n  TAKES ()\n  text: \"Put one of your Battle Cards with [Servant] at the bottom of your deck as the cost, and draw 1 card.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-42\nDEFINE KEYWORD Rejuvenate\n  TAKES ()\n  text: \"A Unison Card with cards beneath it: drop one of them and pay the skill cost, then add the top card of your deck to your life.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-43\nDEFINE KEYWORD \"Spirit Boost\"\n  TAKES (x: number)\n  text: \"Part of a skill's cost: remove X markers from your Unison Card. A skill whose [Spirit Boost] can't be paid can't be activated.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-45\nDEFINE KEYWORD Empower\n  TAKES (color: color, x: number)\n  text: \"When you play this Unison Card over one whose colour matches, you may move up to Y markers from the Unison being replaced onto this one. An [Empower] naming no colour takes them from a Unison of any colour.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-46\nDEFINE KEYWORD \"Z-Awaken\"\n  TAKES ()\n  text: \"From the Z-Deck, once a turn: pay the Z-Energy cost and the skill cost and place this Z-Leader on top of your already-awakened Leader, which has to match the printed description. The stack is one card from then on.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-47\nDEFINE KEYWORD \"Z-Stack\"\n  TAKES (x: number)\n  text: \"When this Z-Card is placed on your Leader or into a Battle or Unison Area, put up to X cards matching the printed description from your Z-Deck underneath it. They become part of the card on top.\"\n  -- Stage 7 (#153–#157)\n",
  "ops.rules": "-- The macros: every op the cards use that is not a primitive, written over\n-- the ones that are.\n--\n-- `docs/arena-ruleset-spec.md` §2 is the decision — nineteen primitives, and\n-- one `DEFINE OP` here for each of the thirty-one rows `OP_CLASS` marks\n-- *macro*. A macro is not a deletion: `power(…)` keeps its `OP_SCHEMA` row,\n-- keeps printing as itself and keeps round-tripping by that name; this file\n-- says only what it *means*, and `rulesets/expand.ts` is what lowers a program\n-- written in these ops to a program written in the primitives.\n--\n-- **Most rows are not declared yet, and the table below is why.** Writing one\n-- that silently dropped an argument would be worse than none: it would\n-- validate, it would expand, the sweep in `scripts/verify/language.ts` would\n-- pass, and the rule it claimed to explain would be wrong. Each row names the\n-- one thing it waits on. The expander is built and tested against fixtures, so\n-- the first row that becomes writable is a declaration here and nothing else.\n--\n-- ── what each row waits on ────────────────────────────────────────────────\n--\n--   param     answered (#273): inside a DEFINE OP body `$name` may stand in\n--             every field position — a duration, a side, an area, a mode or\n--             any closed list (declared `word`), a list of strings\n--             (`strings`), a whole program (`ops`) — and in a selector's\n--             count, `TOP n`, side and area. A row still listing it below is\n--             waiting on the rest of its line, not on the grammar.\n--   decline   `may` offers a program and the answer to take none of it: two\n--             options, the second empty (spec §2.3). `chooseMode` drops an\n--             empty option without asking, asks the master rather than the\n--             `chooser` the call names, and binds no answer for\n--             `did(what: may)` to read — the requirement §2.3 puts on the\n--             primitive. Lowered today, \"you may\" would never be asked.\n--   cause     `move` must carry a cause — `damage`, `ko`, `combo`, `effect`\n--             and a plain draw are one move told apart by it, and the triggers\n--             read it (spec §2.5-2). `moveTo` has no such field today.\n--   subject   `modifyAttr` reaches one card and six attributes; the rows below\n--             need a *player* and the *battle in progress* as subjects, and\n--             `mode`, `markers`, `keywords`, `hidden`, `faceUp` and `flipped`\n--             as attributes (spec §2.5-1, §2.5-3).\n--   negate    the `negate` primitive — the general form of `negateSkills` —\n--             is not an op yet (spec §2.2).\n--   replace   the `replace` primitive is not an op yet (spec §2.2, #125).\n--   cost      the `costModifier` primitive is not an op yet: a price is not a\n--             number, which is the whole of spec §2.5-4.\n--   audience  `reveal` shows a card to both players; `look` is the same act\n--             with a narrower audience (20-11), and the field that says which\n--             does not exist.\n--   maths     an amount cannot subtract, so \"until you have n life\" cannot be\n--             written (spec §2.5-5).\n--\n-- ── the thirty-one macros ─────────────────────────────────────────────────\n--\n--   op                   lowers to                waits on\n--   draw                 move                     param, cause\n--   discard              choose + move            param, cause\n--   damage               move                     param, cause\n--   mill                 move                     param, cause\n--   addLife              move                     param, cause\n--   lifeDownTo           move                     param, cause, maths\n--   energyMarker         modifyAttr               param, subject\n--   look                 reveal                   param, audience\n--   ko                   move                     cause\n--   switchMode           modifyAttr               param, subject\n--   power                modifyAttr               declared (#273)\n--   comboPower           modifyAttr               declared (#273)\n--   grant                modifyAttr               param, subject\n--   negateSkills         negate                   param, negate\n--   negateSkillsOfKind   negate                   param, negate\n--   hidden               modifyAttr               param, subject\n--   redirectAttack       modifyAttr               subject\n--   comboFrom            move + negate            param, cause, negate\n--   flip                 modifyAttr               subject\n--   faceUp               modifyAttr               param, subject\n--   addMarker            modifyAttr               param, subject\n--   removeMarker         modifyAttr               param, subject\n--   costReduction        costModifier             param, cost\n--   negateKeyword        negate                   param, negate\n--   gains                modifyAttr               param, subject\n--   replaceLeave         replace                  param, replace\n--   altCost              costModifier             param, cost\n--   resolvingPlay        replace                  param, replace\n--   negateAttack         replace                  replace\n--   negateCounter        replace                  replace\n--   negateOwnSkill       negate                   param, negate\n--   may                  chooseMode               decline\n--\n-- Three rows wait on nothing but a primitive that is only a field away\n-- (`ko`, `redirectAttack`, `flip`) and three on `replace` alone\n-- (`negateAttack`, `negateCounter`, and `resolvingPlay` once `param` is\n-- answered). Those are the first this file should gain.\n\n-- ── the two numbers a card changes (§2.3, 20-5) ────────────────────────────\n--\n-- A change to power or combo power is one act — one attribute of one card,\n-- by an expression, for a duration — and `modifyAttr` is that act. The two\n-- rows differ in nothing but which attribute they name, which is the whole of\n-- the argument the spec's table makes.\n\n-- §20-5 — \"+5000 power for the turn\", \"+X power\", \"power +5000 for each …\"\nDEFINE OP power\n  TAKES (target: ref, amount: amount, until: duration)\n  DO {\n    modifyAttr(target: $target, attr: power, amount: $amount, until: $until)\n  }\n  text: \"the card's power changes by the amount, for the duration\"\n  doc: \"what `power` means: one attribute of one card, changed by an expression until a moment\"\n\n-- §20-5 — \"+10000 combo power for the turn\"\nDEFINE OP comboPower\n  TAKES (target: ref, amount: amount, until: duration)\n  DO {\n    modifyAttr(target: $target, attr: comboPower, amount: $amount, until: $until)\n  }\n  text: \"the card's combo power changes by the amount, for the duration\"\n  doc: \"the same act as `power`, on the other printed number\"\n",
  "triggers.rules": "-- ───────────────────────────────────────────────────────────────────────────\n-- The moments an [Auto] or a [Counter] answers to (manual 9-6), as the events\n-- that *are* them.\n--\n-- A trigger is a name in the legacy engine, matched against the event log by\n-- TypeScript. Here it is an event pattern, so a game can declare its own\n-- moments without code — and so the engine's moments can be read against the\n-- manual rather than against `pendTriggers`.\n--\n-- Four conventions hold across the file.\n--\n--   ON <event>(field: value, …)\n--     The event and the fields that have to match. Event names are the\n--     definition's own; which of them a game fires is Stage 4's business.\n--     Only `from`, `to`, `in`, `area` and `zone` name a DEFINE ZONE and are\n--     checked by the loader — every other argument is a word about the event\n--     itself, so `attackDeclared(target: leader)` is a part in the attack and\n--     not a place.\n--\n--   watcher: controller | opponent | both\n--     Whose cards in play are asked, when the moment is not the answering\n--     card's own. `controller` is the side the event is about (the moved\n--     card's master, the damaged player); `opponent` is the other one.\n--     Left out, only the card the event is about answers.\n--\n--   WHERE\n--     A condition on the answering side rather than on the event.\n--     `isTurnPlayer(who: you)` is what \"your Charge Phase\" means on a card,\n--     and \"your opponent's turn\" is the same condition from the other chair\n--     (7-1) — never a duration.\n--\n--   BIND\n--     What the event's card is called inside the program: \"self\" when the\n--     moment happened to the answering card, \"subject\" when it happened to\n--     another card that the answering card is watching. A watcher list that\n--     includes the card itself (a Unison paying its own [Spirit Boost], a\n--     Life card turned face up) binds \"subject\" all the same — there it is\n--     the same card.\n--\n-- The names are the `Trigger` union's, and `text:` is the record's WHEN in\n-- words, so `scripts/verify/rulesets.ts` can hold the two to one list.\n-- The five `counter:*` declarations at the foot are the counter windows\n-- (4-3, 9-7): the moments a [Counter] answers to rather than an [Auto], and\n-- the only names here a card's WHEN never says.\n-- ───────────────────────────────────────────────────────────────────────────\n\n-- ── playing and placing ────────────────────────────────────────────────────\n\n-- §6-2-4 — when your Leader is placed\nDEFINE TRIGGER leaderPlaced\n  ON moved(to: leader)\n  BIND \"self\"\n  text: \"when your Leader is placed\"\n\n-- §9-6-9-4 — when this card is played\nDEFINE TRIGGER played\n  ON moved(asPlay: true, to: [battle, unison])\n  BIND \"self\"\n  text: \"when this card is played\"\n\n-- §5-5 — when you play a card\nDEFINE TRIGGER youPlayed\n  ON moved(asPlay: true, to: [battle, unison], watcher: controller)\n  BIND \"subject\"\n  text: \"when you play a card\"\n\n-- §5-5 — when your opponent plays a card\nDEFINE TRIGGER opponentPlayed\n  ON moved(asPlay: true, to: [battle, unison], watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent plays a card\"\n\n-- §5-5-4 — when this card is placed in a Battle Area\nDEFINE TRIGGER placed\n  ON moved(asPlay: false, to: battle)\n  BIND \"self\"\n  text: \"when this card is placed in a Battle Area\"\n\n-- ── battles (8-1 … 8-5) ────────────────────────────────────────────────────\n\n-- §8-1-3 — when this card attacks\nDEFINE TRIGGER attacks\n  ON attackDeclared(role: attacker)\n  BIND \"self\"\n  text: \"when this card attacks\"\n\n-- §8-1-3 — when this card is attacked\nDEFINE TRIGGER attacked\n  ON attackDeclared(role: target)\n  BIND \"self\"\n  text: \"when this card is attacked\"\n\n-- §8-1-3 — when your opponent attacks\nDEFINE TRIGGER opponentAttacks\n  ON attackDeclared(watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent attacks\"\n\n-- §8-1-3 — when your Leader is attacked\nDEFINE TRIGGER yourLeaderAttacked\n  ON attackDeclared(target: leader, watcher: controller)\n  BIND \"subject\"\n  text: \"when your Leader is attacked\"\n\n-- §8-2 — at the start of the offense step\nDEFINE TRIGGER offenseStart\n  ON stepStart(step: offense)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the start of the offense step\"\n\n-- §8-3 — at the start of the defense step\nDEFINE TRIGGER defenseStart\n  ON stepStart(step: defense)\n  WHERE isTurnPlayer(who: opponent)\n  BIND \"self\"\n  text: \"at the start of the defense step\"\n\n-- §8-4 — at the start of the damage step\nDEFINE TRIGGER damageStart\n  ON stepStart(step: damage, watcher: both)\n  BIND \"self\"\n  text: \"at the start of the damage step\"\n\n-- §8-5 — at the end of the battle\nDEFINE TRIGGER battleEnd\n  ON stepStart(step: battleEnd, watcher: both)\n  BIND \"self\"\n  text: \"at the end of the battle\"\n\n-- ── KOs (5-12, 21-14) ──────────────────────────────────────────────────────\n\n-- §5-12 — when this card is KO'd\nDEFINE TRIGGER koed\n  ON ko\n  BIND \"self\"\n  text: \"when this card is KO'd\"\n\n-- §21-14 — when this card KOs a card\nDEFINE TRIGGER kos\n  ON ko(role: cause)\n  BIND \"self\"\n  text: \"when this card KOs a card\"\n\n-- §21-14 — when one of your cards is KO'd\nDEFINE TRIGGER yourCardKoed\n  ON ko(watcher: controller)\n  BIND \"subject\"\n  text: \"when one of your cards is KO'd\"\n\n-- §21-14 — when an opponent's card is KO'd\nDEFINE TRIGGER opponentCardKoed\n  ON ko(watcher: opponent)\n  BIND \"subject\"\n  text: \"when an opponent's card is KO'd\"\n\n-- ── leaving a Battle Area (3-1, 9-6-9) ─────────────────────────────────────\n\n-- §3-1-5 — when this card is removed from a Battle Area by a skill\nDEFINE TRIGGER removedFromBattle\n  ON moved(by: skill, from: battle)\n  BIND \"self\"\n  text: \"when this card is removed from a Battle Area by a skill\"\n\n-- §3-1-5 — when this card is removed from a Battle Area by an opponent's skill\nDEFINE TRIGGER removedByOpponent\n  ON moved(by: skill, byOpponent: true, from: battle)\n  BIND \"self\"\n  text: \"when this card is removed from a Battle Area by an opponent's skill\"\n\n-- §3-1-5 — when a skill sends this card from a Battle Area to the Drop\nDEFINE TRIGGER droppedFromBattle\n  ON moved(by: skill, from: battle, to: drop)\n  BIND \"self\"\n  text: \"when a skill sends this card from a Battle Area to the Drop\"\n\n-- §3-1-5 — when this card goes from a Battle Area to the Drop\nDEFINE TRIGGER leftBattleToDrop\n  ON moved(from: battle, to: drop)\n  BIND \"self\"\n  text: \"when this card goes from a Battle Area to the Drop\"\n\n-- ── damage and life (5-10, 3-9, 21-3) ──────────────────────────────────────\n\n-- §5-10 — when this card deals damage\nDEFINE TRIGGER dealtDamage\n  ON damage(role: source)\n  BIND \"self\"\n  text: \"when this card deals damage\"\n\n-- §21-3 — when you take damage from a skill\nDEFINE TRIGGER youTookDamage\n  ON damage(by: skill, watcher: controller)\n  BIND \"subject\"\n  text: \"when you take damage from a skill\"\n\n-- §21-3 — when your opponent takes damage from a skill\nDEFINE TRIGGER opponentTookDamage\n  ON damage(by: skill, watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent takes damage from a skill\"\n\n-- §3-9 — when a card leaves your life\nDEFINE TRIGGER lifeLeft\n  ON moved(from: life, watcher: controller)\n  BIND \"subject\"\n  text: \"when a card leaves your life\"\n\n-- §3-9-2-1 — when a card in your life is flipped face up\nDEFINE TRIGGER flippedFaceUp\n  ON faceUpTurned(in: life, watcher: controller)\n  BIND \"subject\"\n  text: \"when a card in your life is flipped face up\"\n\n-- ── the turn (7-1 … 7-4) ───────────────────────────────────────────────────\n\n-- §7-2 — at the start of your Charge Phase\nDEFINE TRIGGER chargeStart\n  ON phaseStart(phase: charge)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the start of your Charge Phase\"\n\n-- §7-1 — at the start of your opponent's turn\nDEFINE TRIGGER opponentTurnStart\n  ON phaseStart(phase: charge)\n  WHERE isTurnPlayer(who: opponent)\n  BIND \"self\"\n  text: \"at the start of your opponent's turn\"\n\n-- §7-3 — at the start of your Main Phase\nDEFINE TRIGGER mainStart\n  ON phaseStart(phase: main)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the start of your Main Phase\"\n\n-- §7-3 — at the start of your opponent's Main Phase\nDEFINE TRIGGER opponentMainStart\n  ON phaseStart(phase: main)\n  WHERE isTurnPlayer(who: opponent)\n  BIND \"self\"\n  text: \"at the start of your opponent's Main Phase\"\n\n-- §7-3 — at the end of your Main Phase\nDEFINE TRIGGER mainEnd\n  ON phaseEnd(phase: main)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the end of your Main Phase\"\n\n-- §7-4 — at the end of your turn\nDEFINE TRIGGER turnEnd\n  ON phaseStart(phase: end)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the end of your turn\"\n\n-- §7-1 — at the end of your opponent's turn\nDEFINE TRIGGER opponentTurnEnd\n  ON phaseStart(phase: end)\n  WHERE isTurnPlayer(who: opponent)\n  BIND \"self\"\n  text: \"at the end of your opponent's turn\"\n\n-- ── combos (5-7, 8-5-8) ────────────────────────────────────────────────────\n\n-- §8-5-8 — when this card is used in a combo\nDEFINE TRIGGER comboed\n  ON moved(from: combo)\n  BIND \"self\"\n  text: \"when this card is used in a combo\"\n\n-- §5-7 — when you combo\nDEFINE TRIGGER youCombo\n  ON comboUsed(watcher: controller)\n  BIND \"subject\"\n  text: \"when you combo\"\n\n-- §5-7 — when your opponent combos\nDEFINE TRIGGER opponentCombos\n  ON comboUsed(watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent combos\"\n\n-- ── keyword activations (22) ───────────────────────────────────────────────\n\n-- §22-4 — when this card activates [Blocker]\nDEFINE TRIGGER blockerUsed\n  ON keywordActivated(keyword: Blocker)\n  BIND \"self\"\n  text: \"when this card activates [Blocker]\"\n\n-- §22-5 — when a card evolves into this card\nDEFINE TRIGGER evolvedInto\n  ON keywordActivated(keyword: Evolve)\n  BIND \"subject\"\n  text: \"when a card evolves into this card\"\n\n-- §22-5 — when you use this card's [Evolve] from your hand\nDEFINE TRIGGER evolveFromHandActivated\n  ON keywordActivated(from: hand, keyword: Evolve)\n  BIND \"self\"\n  text: \"when you use this card's [Evolve] from your hand\"\n\n-- §22-13 — when you activate a [Union] skill\nDEFINE TRIGGER unionActivated\n  ON keywordActivated(keyword: Union, watcher: controller)\n  BIND \"subject\"\n  text: \"when you activate a [Union] skill\"\n\n-- §22-13-5 — when this card's [Union-Absorb] is activated\nDEFINE TRIGGER unionAbsorbActivated\n  ON keywordActivated(keyword: \"Union-Absorb\")\n  BIND \"self\"\n  text: \"when this card's [Union-Absorb] is activated\"\n\n-- §22-41 — when you activate an [Overlord] skill\nDEFINE TRIGGER overlordActivated\n  ON keywordActivated(keyword: Overlord, watcher: controller)\n  BIND \"subject\"\n  text: \"when you activate an [Overlord] skill\"\n\n-- §22-15 — when you play a card using [Over Realm]\nDEFINE TRIGGER overRealmPlayed\n  ON keywordActivated(keyword: \"Over Realm\", watcher: controller)\n  BIND \"subject\"\n  text: \"when you play a card using [Over Realm]\"\n\n-- ── skills and counters (9-6, 9-7, 22-10) ──────────────────────────────────\n\n-- §9-7 — when your opponent activates a [Counter] skill\nDEFINE TRIGGER opponentCounter\n  ON skillActivated(kind: counter, watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent activates a [Counter] skill\"\n\n-- §22-10 — when you activate this card's [Counter] from your hand without paying its energy cost\nDEFINE TRIGGER counterFreeFromHand\n  ON skillActivated(from: hand, kind: counter, paid: false)\n  BIND \"self\"\n  text: \"when you activate this card's [Counter] from your hand without paying its energy cost\"\n\n-- ── modes and markers (1-10, 5-13, 22-32, 22-43) ───────────────────────────\n\n-- §1-10-1 — when this card is rested by one of your skills\nDEFINE TRIGGER restedBySkill\n  ON modeSwitched(by: skill, byOpponent: false, mode: rest)\n  BIND \"self\"\n  text: \"when this card is rested by one of your skills\"\n\n-- §1-10-1 — when your skill rests an opponent's card\nDEFINE TRIGGER restedTheirsBySkill\n  ON modeSwitched(by: skill, mode: rest, watcher: opponent)\n  BIND \"subject\"\n  text: \"when your skill rests an opponent's card\"\n\n-- §22-32-3 — when this card is rested by an [Alliance] skill\nDEFINE TRIGGER restedByAlliance\n  ON modeSwitched(by: Alliance, mode: rest)\n  BIND \"self\"\n  text: \"when this card is rested by an [Alliance] skill\"\n\n-- §5-13 — when a marker is removed from this card\nDEFINE TRIGGER markerRemoved\n  ON markerRemoved\n  BIND \"self\"\n  text: \"when a marker is removed from this card\"\n\n-- §22-43-3 — when you pay a [Spirit Boost] cost from this card\nDEFINE TRIGGER spiritBoostPaid\n  ON markerRemoved(by: \"Spirit Boost\", watcher: controller)\n  BIND \"subject\"\n  text: \"when you pay a [Spirit Boost] cost from this card\"\n\n-- ── areas outside play (3-8, 3-11, 3-13) ───────────────────────────────────\n\n-- §3-8 — when a card goes from your energy to the Drop\nDEFINE TRIGGER energyToDrop\n  ON moved(from: energy, to: drop, watcher: controller)\n  BIND \"subject\"\n  text: \"when a card goes from your energy to the Drop\"\n\n-- §3-11-5 — when your Unison goes to the Drop\nDEFINE TRIGGER unisonToDrop\n  ON moved(from: unison, to: drop)\n  BIND \"self\"\n  text: \"when your Unison goes to the Drop\"\n\n-- §3-13-1 — when this card is added to your Z-Energy\nDEFINE TRIGGER addedToZEnergy\n  ON moved(to: zEnergy)\n  BIND \"self\"\n  text: \"when this card is added to your Z-Energy\"\n\n-- ── the counter windows (4-3, 9-7) ─────────────────────────────────────────\n-- A [Counter] answers to a window rather than to a card's moment, so these\n-- five carry a name a card's WHEN never says. The shape is the same: the\n-- moment as the event that is it.\n\n-- §9-6-6 — the window after a card is played and before it resolves\nDEFINE TRIGGER \"counter:play\"\n  ON counterTiming(watcher: opponent, window: play)\n  BIND \"subject\"\n  text: \"when your opponent plays a card, before it resolves\"\n\n-- §8-1-4 — the window after an attack is declared\nDEFINE TRIGGER \"counter:attack\"\n  ON counterTiming(watcher: opponent, window: attack)\n  BIND \"subject\"\n  text: \"when your opponent declares an attack\"\n\n-- §8-1-4 — the same window, narrowed to an attack a Battle Card made\nDEFINE TRIGGER \"counter:battleCardAttack\"\n  ON counterTiming(attacker: battleCard, watcher: opponent, window: attack)\n  BIND \"subject\"\n  text: \"when your opponent's Battle Card declares an attack\"\n\n-- §9-7-4 — the window after a [Counter] skill is activated\nDEFINE TRIGGER \"counter:counter\"\n  ON counterTiming(watcher: opponent, window: counter)\n  BIND \"subject\"\n  text: \"when your opponent activates a [Counter] skill, before it resolves\"\n\n-- §9-6-6 — the window after a skill is activated\nDEFINE TRIGGER \"counter:skill\"\n  ON counterTiming(watcher: opponent, window: skill)\n  BIND \"subject\"\n  text: \"when your opponent activates a skill, before it resolves\"\n",
  "zones.rules": "-- The areas of the Dragon Ball Super Card Game, as declarations.\n--\n-- Every section cited is `docs/rules/rulemanual.txt`: §3 is the areas\n-- themselves, §1-10 card positions (Active and Rest Mode), §1-11 markers,\n-- §9-1-3-1 where a card's own skills are valid, §20-10 removal from the game\n-- and §23-2 cards placed under other cards.\n--\n-- The manual counts twelve areas (§3). Three more are declared below because\n-- a program has to be able to name them: `removed` (§20-10, where a card\n-- removed from the game is kept, which the manual pointedly says is no area\n-- at all), `under` (§23-2, the cards beneath another card) and `play`, which\n-- is the word for the three areas together in which a card is in play\n-- (§9-1-3-1). Each says so in its own text.\n--\n-- Three conventions, held to on every declaration so that a reader never has to\n-- ask what a missing line meant:\n--   `ordered: true`  the order of the cards is fixed by the rules and no\n--                    player may rearrange it (§3-2-2, §3-9-2). Every other\n--                    area lets its owner change the order freely, and is\n--                    written `ordered: false` rather than left out.\n--   `visibility`     who may read the faces: `none` is a secret area neither\n--                    player may check, `owner` a secret area its own player\n--                    may read, `all` an open area (§3-1-3).\n--   `place`          is this zone a list of cards a player holds? Twelve of the\n--                    fifteen are, and so are `removed` (§20-10) — a card\n--                    removed from the game is kept somewhere even though the\n--                    manual counts it in no area. `play` and `under` are not:\n--                    the first is a word for three zones at once (§9-1-3-1)\n--                    and the second is the pile hanging off one card\n--                    (§23-2-2-2). An interpreter builds a side's zones from\n--                    the ones that are, so this line is what saves it from\n--                    knowing those two names (#139).\n--\n-- Each player possesses one of every area, and two areas of the same name\n-- with different masters are different areas (§3-1-1) — which is what\n-- `owner: player` says. No area of this game is shared.\n\nDEFINE ZONE deck                                                          -- §3-2\n  owner: player\n  visibility: none\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the deck, face down: neither player may check its contents or change its order (3-2-2)\"\n\nDEFINE ZONE hand                                                          -- §3-3\n  owner: player\n  visibility: owner\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the cards a player holds: their own to read and reorder, and no limit on how many (3-3-2, 3-3-4)\"\n\nDEFINE ZONE drop                                                          -- §3-4\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"where KO'd Battle Cards, spent Unison Cards and activated Extra Cards are placed, face up (3-4-1, 3-4-3)\"\n\nDEFINE ZONE leader                                                        -- §3-5\n  owner: player\n  visibility: all\n  ordered: false\n  single: true\n  markers: false\n  inPlay: true\n  host: true\n  place: true\n  modes: [active, rest]\n  text: \"the one Leader Card, face up, which no effect or rule may move out of this area (3-5-1, 3-5-3)\"\n\nDEFINE ZONE battle                                                        -- §3-6\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: true\n  host: true\n  place: true\n  modes: [active, rest]\n  text: \"where Battle Cards and some Extra Cards are played, revealed and active, with no limit on how many (3-6-1, 3-6-3)\"\n\nDEFINE ZONE combo                                                         -- §3-7\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: true\n  place: true\n  text: \"the Battle Cards used in a combo, face up (3-7-1, 3-7-2)\"\n\nDEFINE ZONE energy                                                        -- §3-8\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: true\n  inPlay: false\n  host: false\n  place: true\n  modes: [active, rest]\n  text: \"the energy a player pays costs with, face up and active, and where energy markers are kept (3-8-1, 3-8-3, 1-14-3)\"\n\nDEFINE ZONE life                                                          -- §3-9\n  owner: player\n  visibility: none\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the Leader's life, face down: its order may not be changed, but any card may be chosen when one leaves (3-9-2, 3-9-4)\"\n\nDEFINE ZONE warp                                                          -- §3-10\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"where cards sent to the Warp are placed, face up and readable by either player (3-10-2)\"\n\nDEFINE ZONE unison                                                        -- §3-11\n  owner: player\n  visibility: all\n  ordered: false\n  single: true\n  markers: true\n  inPlay: true\n  host: true\n  place: true\n  modes: [active, rest]\n  text: \"the one Unison Card, revealed and active, carrying the markers its skills are counted in (3-11-3, 3-11-4, 1-11-1)\"\n\nDEFINE ZONE zDeck                                                         -- §3-12\n  owner: player\n  visibility: owner\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the Z-Deck, face down but its owner's to read and reorder; a face-up card in it is in an open area (3-12-2, 3-12-2-1)\"\n\nDEFINE ZONE zEnergy                                                       -- §3-13\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the Z-Energy a player pays Z-Energy costs with, face up (3-13-2, 3-13-3)\"\n\nDEFINE ZONE removed                                                       -- §20-10\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"cards removed from the game: face up, visible to all, and in no area of the game at all (20-10-2, 20-10-3)\"\n\nDEFINE ZONE under                                                         -- §23-2\n  owner: player\n  visibility: all\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: false\n  text: \"the cards beneath another card, face up and skills negated; the area they count as being in is the area of the card on top (23-2-2, 23-2-2-2)\"\n\nDEFINE ZONE play                                                          -- §9-1-3-1\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: true\n  host: false\n  place: false\n  text: \"not a place a card is put: the word for the Leader, Battle and Unison Areas together, the areas a card's own skills are valid in (9-1-3-1)\"\n",
};
